MAP
    NAME "SS_MAP_DREN_CAPTACION_DRENAJE"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_captacion_drenaje.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_DREN_CAPTACION_UBICACION"
        PROJECTION
            'init=epsg:32614'
        END #PROJECION
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from drenaje_captacion using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POLYGON
        LABELITEM "colector"
        CLASS
            NAME "Captacion de drenaje sanitario"
            LABEL
                SIZE 19
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
                TYPE TRUETYPE
                FONT ARIAL
            END #LABEL
            STYLE
                COLOR [color]
                OUTLINECOLOR 0 0 255
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP